class Solution {
public:
    int findDifference(vector<int>& nums, int k) {
        sort(nums.begin(), nums.end());
        int hi = 0, lo = 0, n = nums.size();
        for (int i = n - k; i < n; i++) hi += nums[i];
        for (int i = 0; i < k; i++) lo += nums[i];
        return hi - lo;
    }
};

