class Solution:
    def findDifference(self, nums: List[int], k: int) -> int:
        freq = [0] * 101
        for x in nums: freq[x] += 1
        def sweep(rng):
            s = 0; need = k
            for v in rng:
                take = min(freq[v], need)
                s += take * v; need -= take
                if need == 0: break
            return s
        return sweep(range(100, 0, -1)) - sweep(range(1, 101))

