class Solution {
public:
    int findDifference(vector<int>& nums, int k) {
        int freq[101] = {0};
        for (int x : nums) freq[x]++;
        auto sweep = [&](bool desc) {
            long long s = 0; int need = k;
            for (int t = 0; t < 100; t++) {
                int v = desc ? 100 - t : 1 + t;
                int take = min(freq[v], need);
                s += (long long)take * v; need -= take;
                if (!need) break;
            }
            return s;
        };
        return (int)(sweep(true) - sweep(false));
    }
};

