class Solution {
    public int findDifference(int[] nums, int k) {
        int[] freq = new int[101];
        for (int x : nums) freq[x]++;
        return sweep(freq, k, true) - sweep(freq, k, false);
    }
    private int sweep(int[] freq, int k, boolean desc) {
        long s = 0; int need = k;
        for (int t = 0; t < 100; t++) {
            int v = desc ? 100 - t : 1 + t;
            int take = Math.min(freq[v], need);
            s += (long) take * v; need -= take;
            if (need == 0) break;
        }
        return (int) s;
    }
}

